builder.Services.AddDbContext<AppDbContext>();
builder.Services.AddScoped<IOrderService, OrderService>();

var app = builder.Build();

app.MapGet("/api/orders/{id:guid}", async (
    Guid id,
    IOrderService orders,
    CancellationToken ct) =>
{
    var order = await orders.GetByIdAsync(id, ct);
    return order is null ? Results.NotFound() : Results.Ok(order);
});

app.MapPost("/api/orders", async (
    CreateOrderRequest request,
    IOrderService orders,
    CancellationToken ct) =>
{
    var created = await orders.CreateAsync(request, ct);
    return Results.Created($"/api/orders/{created.Id}", created);
});

var orders = app.MapGroup("/api/orders")
    .AddEndpointFilter<ValidationFilter>()
    .AddEndpointFilter<AuditFilter>();

orders.MapGet("/{id:guid}", GetOrder);
orders.MapPost("/", CreateOrder);

static async Task<IResult> GetOrder(
    Guid id, IOrderService svc, CancellationToken ct)
    => await svc.GetByIdAsync(id, ct) is { } o
        ? Results.Ok(o) : Results.NotFound();

// Filter with DI
public sealed class AuditFilter(ILogger<AuditFilter> logger) : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(
        EndpointFilterInvocationContext ctx,
        EndpointFilterDelegate next)
    {
        logger.LogInformation("{Method} {Route}",
            ctx.HttpContext.Request.Method,
            ctx.HttpContext.Request.Path);
        return await next(ctx);
    }
}

builder.Services.AddKeyedScoped<IPaymentGateway, StripeGateway>("stripe");
builder.Services.AddKeyedScoped<IPaymentGateway, PayPalGateway>("paypal");

app.MapPost("/api/pay/{provider}", async (
    string provider,
    PayRequest body,
    [FromKeyedServices("stripe")] IPaymentGateway stripe,
    [FromKeyedServices("paypal")] IPaymentGateway paypal,
    CancellationToken ct) =>
{
    var gw = provider switch
    {
        "stripe" => stripe,
        "paypal" => paypal,
        _ => throw new BadHttpRequestException("Unknown provider")
    };
    return Results.Ok(await gw.ChargeAsync(body.Amount, ct));
});

