// Integration test proves DI works in minimal API
public class OrdersApiTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;
    public OrdersApiTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.WithWebHostBuilder(b => b.ConfigureServices(s =>
        {
            s.AddScoped<IOrderService, FakeOrderService>(); // override for test
        })).CreateClient();
    }

    [Fact]
    public async Task GetOrder_returns_ok()
    {
        var res = await _client.GetAsync("/api/orders/" + Guid.NewGuid());
        res.EnsureSuccessStatusCode();
    }
}
